/* Tresor-Berater: geschützter Bereich mit Supabase Auth + RLS */
(function(){
  let initialized=false, session=null, products=[], mode="start", editingId=null, adminStage="menu", adminSearchField="", editingConsultationId=null, activeConsultation=null, selectedFamily=null, advisorFilters={group:"",fire:"",standard:"",cls:"",insured:"",use:"private",price:""}, searchExecuted=false, comparisonIds=[], comparisonSnapshot=null;
  const root=()=>document.getElementById("tresorApp");
  const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
  const euro=n=>Number(n||0).toLocaleString("de-DE",{style:"currency",currency:"EUR"});
  const val=id=>document.getElementById(id)?.value??"";
  function shell(){root().innerHTML='<div class="tresor-wrap"><div class="tresor-head"><div><div class="dashboard-eyebrow">SCHLÜSSELDIENST HÖHNE</div><h1>🔐 Tresor-Berater</h1><div class="tresor-muted">Rottner-Produkte finden, vergleichen und verwalten.</div></div><div id="tresorUser"></div></div><div id="tresorBody"></div></div>'}
  function loginView(message=""){root().innerHTML='<div class="tresor-wrap"><div class="tresor-panel tresor-login"><div class="dashboard-eyebrow">INTERNER BEREICH</div><h2>🔐 Anmeldung Tresor-Berater</h2><p class="tresor-muted">Zugriff nur mit einem freigeschalteten Benutzerkonto.</p><div id="tresorLoginMsg" class="tresor-status '+(message?'error':'')+'">'+esc(message)+'</div><div class="tresor-field"><label>E-Mail-Adresse</label><input id="tresorEmail" type="email" autocomplete="username"></div><div class="tresor-field" style="margin-top:10px"><label>Passwort</label><input id="tresorPassword" type="password" autocomplete="current-password"></div><div class="tresor-actions"><button class="btnP" id="tresorLoginBtn">Anmelden</button></div></div></div>';document.getElementById("tresorLoginBtn").onclick=login}
  async function login(){const msg=document.getElementById("tresorLoginMsg");msg.textContent="Anmeldung läuft …";msg.classList.remove("error");const {data,error}=await window.supabaseClient.auth.signInWithPassword({email:val("tresorEmail").trim(),password:val("tresorPassword")});if(error){msg.textContent="Anmeldung fehlgeschlagen. Bitte Zugangsdaten prüfen.";msg.classList.add("error");return}session=data.session;await loadProducts()}
  async function logout(){await window.supabaseClient.auth.signOut();session=null;products=[];loginView()}
  function homeView(){return '<div class="tresor-home-intro"><div class="dashboard-eyebrow">TRESOR-BEREICH</div><h2>Was möchtest du machen?</h2><p>Wähle den gewünschten Bereich aus.</p></div><div class="tresor-home-grid"><button class="tresor-home-card" data-mode="berater"><span class="tresor-home-icon">＋</span><strong>Neue Beratung</strong><small>Kundenanforderungen erfassen und passende Tresore vergleichen</small><b>›</b></button><button class="tresor-home-card" data-mode="kunden"><span class="tresor-home-icon">👥</span><strong>Gespeicherte Beratung</strong><small>Bestehende Kunden und Beratungen öffnen und weiterbearbeiten</small><b>›</b></button><button class="tresor-home-card" data-mode="produkte"><span class="tresor-home-icon">📦</span><strong>Alle Produkte</strong><small>Gesamten Tresorbestand in einer übersichtlichen Liste ansehen</small><b>›</b></button><button class="tresor-home-card" data-mode="verwaltung"><span class="tresor-home-icon">⚙️</span><strong>Produktverwaltung</strong><small>Produkte anlegen, bearbeiten oder löschen</small><b>›</b></button></div>'}
  function sectionNav(){return '<div class="tresor-section-nav"><button class="btnS" type="button" data-mode="start">← Tresor-Übersicht</button><span>'+({berater:"Neue Beratung",kunden:"Gespeicherte Beratung",produkte:"Alle Produkte",verwaltung:"Produktverwaltung"}[mode]||"")+'</span></div>'}
  function setMode(m){mode=m;render()}
  function render(){const body=document.getElementById("tresorBody");document.getElementById("tresorUser").innerHTML='<button class="btnS" id="tresorLogout">Abmelden</button>';document.getElementById("tresorLogout").onclick=logout;body.innerHTML=(mode==="start"?homeView():sectionNav()+(mode==="berater"?advisor():mode==="kunden"?customerCasesView():mode==="produkte"?productsView():admin()));body.querySelectorAll("[data-mode]").forEach(b=>b.onclick=()=>setMode(b.dataset.mode));if(mode==="berater")bindAdvisor();else if(mode==="kunden")bindCustomerCases();else if(mode==="produkte")bindProductsView();else if(mode==="verwaltung")bindAdmin()}
  const advisorFilterOptions={
    group:[["","Alle Tresore"],["Waffenschrank","Waffenschränke"],["Wertschutzschrank","Wertschutzschränke"],["Feuerschutztresor","Feuerschutztresore"],["Möbeltresor","Möbeltresore"],["Hotelzimmertresor","Hotelzimmertresore"],["Einwurftresor","Einwurftresore"],["Wandtresor","Wandtresore"],["Schlüsseltresor","Schlüsseltresore"],["Datentresor","Datentresore"]],
    fire:[["","Keine Vorgabe"],["unknown","Keine Angabe"],["none","Ohne Feuerschutz"],["conditional","Bedingter Feuerschutz"],["tested:30","30 Minuten"],["tested:60","60 Minuten"],["tested:120","120 Minuten"]],
    standard:[["","Keine Vorgabe"],["EN 1143-1","EN 1143-1"],["EN 14450","EN 14450"]],
    cls:[["","Alle Klassen"],["S1","S1"],["S2","S2"],["0","0"],["I","I"],["II","II"],["III","III"],["IV","IV"],["V","V"]],
    insured:[["","Keine Vorgabe"],["20000","Bis 20.000 €"],["50000","Bis 50.000 €"],["100000","Bis 100.000 €"]],
    use:[["private","Privat"],["commercial","Gewerblich"]]
  };
  const advisorFilterLabels={group:"Produktgruppe",fire:"Feuerschutz",standard:"Einbruchschutz-Norm",cls:"Sicherheitsklasse",insured:"Versicherungswert",use:"Nutzung",price:"Maximaler Verkaufspreis"};
  function filterValueLabel(key){if(key==="price")return advisorFilters.price?Number(advisorFilters.price).toLocaleString("de-DE")+" €":"Beliebig";return (advisorFilterOptions[key]||[]).find(x=>x[0]===advisorFilters[key])?.[1]||"Keine Vorgabe"}
  function advisor(){const tiles=["group","fire","standard","cls","insured","use","price"];return '<div class="tresor-panel"><div class="sec">KUNDENANFORDERUNGEN</div><p class="tresor-muted">Wähle zuerst die Produktgruppe und anschließend die Anforderungen des Kunden. Die Suche startet erst mit „Passende Tresore anzeigen“.</p><div class="tresor-filter-grid">'+tiles.map(k=>'<button type="button" class="tresor-filter-tile" data-open-filter="'+k+'"><span>'+advisorFilterLabels[k]+'</span><strong id="filterValue_'+k+'">'+filterValueLabel(k)+'</strong><small>Zum Auswählen antippen</small></button>').join("")+'</div><div class="tresor-actions"><button class="btnP" id="filterSafes">🔎 Passende Tresore anzeigen</button><button class="btnS" id="resetSafeFilter">Zurücksetzen</button></div></div><div id="advisorFilterModal" class="tresor-filter-modal" aria-hidden="true"><div class="tresor-filter-dialog"><div class="tresor-filter-dialog-head"><strong id="advisorFilterTitle">Auswahl</strong><button type="button" class="btnS" id="closeAdvisorFilter">Schließen ✕</button></div><div id="advisorFilterOptions" class="tresor-filter-options"></div></div></div><div id="consultationEditor"></div><div id="tresorCompareBar" class="tresor-compare-bar"></div><div id="tresorResults" class="tresor-results"></div><p class="tresor-muted" style="margin-top:12px">Hinweis: Versicherungswerte sind katalogabhängige Richtwerte und keine Versicherungszusage. Feuerschutz und Einbruchschutz werden anhand der hinterlegten Produktdaten gefiltert.</p>'}
  function openAdvisorFilter(key){const modal=document.getElementById("advisorFilterModal");if(!modal)return;document.getElementById("advisorFilterTitle").textContent=advisorFilterLabels[key]||"Auswahl";const box=document.getElementById("advisorFilterOptions");if(key==="price"){box.innerHTML='<div class="tresor-price-filter"><label>Maximaler Verkaufspreis brutto (€)</label><input id="advisorPriceInput" type="number" min="0" step="50" placeholder="Kein Preislimit" value="'+esc(advisorFilters.price)+'"><button class="btnP" id="applyAdvisorPrice">Übernehmen</button></div>';document.getElementById("applyAdvisorPrice").onclick=()=>{advisorFilters.price=document.getElementById("advisorPriceInput").value;closeAdvisorFilter();updateAdvisorFilterTiles()}}else{box.innerHTML=(advisorFilterOptions[key]||[]).map(([v,label])=>'<button type="button" class="tresor-filter-option '+(advisorFilters[key]===v?"selected":"")+'" data-filter-value="'+esc(v)+'">'+esc(label)+(advisorFilters[key]===v?' <span>✓</span>':'')+'</button>').join("");box.querySelectorAll("[data-filter-value]").forEach(b=>b.onclick=()=>{advisorFilters[key]=b.dataset.filterValue;closeAdvisorFilter();updateAdvisorFilterTiles()})}modal.classList.add("open");modal.setAttribute("aria-hidden","false")}
  function closeAdvisorFilter(){const m=document.getElementById("advisorFilterModal");if(m){m.classList.remove("open");m.setAttribute("aria-hidden","true")}}
  function updateAdvisorFilterTiles(){Object.keys(advisorFilterLabels).forEach(k=>{const el=document.getElementById("filterValue_"+k);if(el)el.textContent=filterValueLabel(k)})}
  function bindAdvisor(){document.querySelectorAll("[data-open-filter]").forEach(b=>b.onclick=()=>openAdvisorFilter(b.dataset.openFilter));document.getElementById("closeAdvisorFilter").onclick=closeAdvisorFilter;document.getElementById("advisorFilterModal").onclick=e=>{if(e.target.id==="advisorFilterModal")closeAdvisorFilter()};document.getElementById("filterSafes").onclick=()=>{selectedFamily=null;searchExecuted=true;showResults()};document.getElementById("resetSafeFilter").onclick=()=>{advisorFilters={group:"",fire:"",standard:"",cls:"",insured:"",use:"private",price:""};searchExecuted=false;selectedFamily=null;updateAdvisorFilterTiles();document.getElementById("tresorResults").innerHTML="";renderCompareBar()};renderCompareBar();if(searchExecuted)showResults();else document.getElementById("tresorResults").innerHTML='<div class="tresor-empty">Wähle die Anforderungen aus und starte anschließend die Suche.</div>';renderConsultationEditor()}
  function toggleComparison(id){comparisonSnapshot=null;const key=String(id);if(comparisonIds.includes(key))comparisonIds=comparisonIds.filter(x=>x!==key);else if(comparisonIds.length<3)comparisonIds.push(key);else{alert("Du kannst maximal drei Tresore für den Vergleich auswählen.");return}showResults()}
  function selectedComparisonProducts(){return comparisonSnapshot||comparisonIds.map(id=>products.find(p=>String(p.id)===id)).filter(Boolean)}
  function renderCompareBar(){const bar=document.getElementById("tresorCompareBar");if(!bar)return;const chosen=selectedComparisonProducts();bar.innerHTML='<div class="tresor-compare-summary"><div><strong>Dein Kundenvergleich</strong><span>'+chosen.length+' von 3 Tresoren ausgewählt</span></div><div class="tresor-compare-actions">'+(chosen.length?'<button class="btnS" type="button" id="clearCompare">Auswahl leeren</button>':'') +(chosen.length&&!editingConsultationId?'<button class="btnS" type="button" id="saveConsultation">Kundenberatung speichern</button>':'')+'<button class="btnP" type="button" id="makeComparePdf" '+(chosen.length<2?'disabled':'')+'>PDF-Vergleich erstellen</button></div></div>'+(chosen.length?'<div class="tresor-compare-chips">'+chosen.map(p=>'<span>'+esc(p.model)+' <button type="button" data-remove-compare="'+esc(p.id)+'" aria-label="Entfernen">×</button></span>').join("")+'</div>':'<p class="tresor-muted">Markiere zwei oder drei Tresore in der Ergebnisliste. Du kannst die Auswahl serienübergreifend zusammenstellen.</p>');document.getElementById("makeComparePdf")?.addEventListener("click",createComparisonPdf);document.getElementById("saveConsultation")?.addEventListener("click",showSaveConsultationForm);document.getElementById("clearCompare")?.addEventListener("click",()=>{comparisonIds=[];comparisonSnapshot=null;showResults()});bar.querySelectorAll("[data-remove-compare]").forEach(b=>b.addEventListener("click",()=>toggleComparison(b.dataset.removeCompare)))}

  function showSaveConsultationForm(){
    if(document.getElementById("saveConsultationPanel"))return;
    const panel=document.createElement("div");panel.id="saveConsultationPanel";panel.className="tresor-panel";
    panel.innerHTML='<div class="sec">KUNDENBERATUNG SPEICHERN</div><form id="saveConsultationForm"><div class="tresor-grid"><div class="tresor-field"><label>Kundenname *</label><input id="cName" required></div><div class="tresor-field"><label>Telefon (optional)</label><input id="cPhone" type="tel"></div><div class="tresor-field"><label>E-Mail (optional)</label><input id="cEmail" type="email"></div><div class="tresor-field"><label>Status</label><select id="cStatus"><option value="open">Angebot offen</option><option value="callback">Rückruf geplant</option><option value="sold">Kunde hat gekauft</option><option value="lost">Kein Interesse</option></select></div><div class="tresor-field"><label>Wiedervorlage</label><input id="cFollowUp" type="date"></div><div class="tresor-field" style="grid-column:1/-1"><label>Interne Notiz</label><textarea id="cNotes"></textarea></div></div><div class="tresor-actions"><button class="btnP" type="submit">Dauerhaft speichern</button><button class="btnS" type="button" id="cancelSaveConsultation">Abbrechen</button></div><div id="saveConsultationMsg" class="tresor-status"></div></form>';
    document.getElementById("tresorCompareBar").after(panel);
    document.getElementById("cancelSaveConsultation").onclick=()=>panel.remove();
    document.getElementById("saveConsultationForm").onsubmit=saveConsultation;
  }
  function renderConsultationEditor(){
    const host=document.getElementById("consultationEditor");if(!host)return;
    if(!editingConsultationId||!activeConsultation){host.innerHTML="";return;}
    const c=activeConsultation;
    host.innerHTML='<div class="tresor-panel" style="margin-top:16px;border:2px solid #4c9b75"><div class="sec">BESTEHENDE KUNDENBERATUNG BEARBEITEN</div><p class="tresor-muted">Kunde: <strong>'+esc(c.customer_name)+'</strong> · Die geladenen Daten kannst du hier ändern. Tresore unten hinzufügen oder über das × entfernen.</p><form id="editConsultationForm"><div class="tresor-grid"><div class="tresor-field"><label>Kundenname *</label><input id="eName" required value="'+esc(c.customer_name||"")+'"></div><div class="tresor-field"><label>Telefon</label><input id="ePhone" type="tel" value="'+esc(c.phone||"")+'"></div><div class="tresor-field"><label>E-Mail</label><input id="eEmail" type="email" value="'+esc(c.email||"")+'"></div><div class="tresor-field"><label>Status</label><select id="eStatus"><option value="open">Angebot offen</option><option value="callback">Rückruf geplant</option><option value="sold">Kunde hat gekauft</option><option value="lost">Kein Interesse</option></select></div><div class="tresor-field"><label>Wiedervorlage</label><input id="eFollowUp" type="date" value="'+esc(c.follow_up_at||"")+'"></div><div class="tresor-field" style="grid-column:1/-1"><label>Interne Notizen</label><textarea id="eNotes">'+esc(c.notes||"")+'</textarea></div></div><div class="tresor-actions"><button class="btnP" type="submit">Änderungen speichern</button><button class="btnS" type="button" id="cancelEditConsultation">Zur Kundenliste</button></div><div id="editConsultationMsg" class="tresor-status"></div></form></div>';
    document.getElementById("eStatus").value=c.status||"open";
    document.getElementById("editConsultationForm").onsubmit=updateConsultation;
    document.getElementById("cancelEditConsultation").onclick=()=>{editingConsultationId=null;activeConsultation=null;comparisonIds=[];comparisonSnapshot=null;mode="kunden";render()};
  }
  async function updateConsultation(e){
    e.preventDefault();const msg=document.getElementById("editConsultationMsg");const chosen=selectedComparisonProducts();
    const payload={customer_name:val("eName").trim(),phone:val("ePhone").trim()||null,email:val("eEmail").trim()||null,status:val("eStatus"),follow_up_at:val("eFollowUp")||null,notes:val("eNotes").trim()||null,product_ids:chosen.map(p=>p.id),product_snapshot:chosen,updated_at:new Date().toISOString()};
    const {error}=await window.supabaseClient.from("safe_consultations").update(payload).eq("id",editingConsultationId);
    if(error){msg.textContent="Änderungen konnten nicht gespeichert werden: "+error.message;msg.classList.add("error");return;}
    editingConsultationId=null;activeConsultation=null;comparisonIds=[];comparisonSnapshot=null;mode="kunden";render();
  }
  async function saveConsultation(e){
    e.preventDefault();const msg=document.getElementById("saveConsultationMsg");const chosen=selectedComparisonProducts();
    const payload={created_by:session.user.id,customer_name:val("cName").trim(),phone:val("cPhone").trim()||null,email:val("cEmail").trim()||null,status:val("cStatus"),follow_up_at:val("cFollowUp")||null,notes:val("cNotes").trim()||null,product_ids:chosen.map(p=>p.id),product_snapshot:chosen};
    const {error}=await window.supabaseClient.from("safe_consultations").insert(payload);
    if(error){msg.textContent="Speichern fehlgeschlagen: "+error.message;msg.classList.add("error");return;}
    msg.textContent="Beratung gespeichert.";comparisonIds=[];comparisonSnapshot=null;
    setTimeout(()=>{mode="kunden";render();},500);
  }
  function customerCasesView(){return '<div class="tresor-panel"><div class="sec">GESPEICHERTE KUNDENBERATUNGEN</div><p class="tresor-muted">Gemeinsame Kundenkartei für alle angemeldeten Mitarbeiter.</p><div id="customerCasesList">Lade Beratungen …</div></div>'}
  async function bindCustomerCases(){
    const box=document.getElementById("customerCasesList");
    const {data,error}=await window.supabaseClient.from("safe_consultations").select("*").order("created_at",{ascending:false});
    if(error){box.textContent="Fehler beim Laden: "+error.message;return;}
    if(!data||!data.length){box.innerHTML='<div class="tresor-empty">Noch keine Beratungen gespeichert.</div>';return;}
    const labels={open:"Angebot offen",callback:"Rückruf geplant",sold:"Kunde hat gekauft",lost:"Kein Interesse"};
    box.innerHTML='<div class="tresor-table-wrap"><table class="tresor-table"><thead><tr><th>Kunde</th><th>Kontakt</th><th>Tresorauswahl</th><th>Status</th><th>Wiedervorlage</th><th>Aktion</th></tr></thead><tbody>'+
      data.map(c=>'<tr><td><strong>'+esc(c.customer_name)+'</strong><br><small>'+new Date(c.created_at).toLocaleDateString("de-DE")+'</small></td><td>'+esc(c.phone||"–")+'<br>'+esc(c.email||"")+'</td><td>'+esc((c.product_snapshot||[]).map(p=>p.model).join(", "))+'</td><td><select data-case-status="'+c.id+'">'+Object.entries(labels).map(([k,v])=>'<option value="'+k+'" '+(c.status===k?'selected':'')+'>'+v+'</option>').join("")+'</select></td><td>'+(c.follow_up_at?new Date(c.follow_up_at+"T12:00:00").toLocaleDateString("de-DE"):"–")+'</td><td><button class="btnS" data-open-case="'+c.id+'">Öffnen</button> '+(c.phone?'<a href="tel:'+esc(c.phone)+'" class="btnS">Anrufen</a>':'')+' <button class="btnS" data-delete-case="'+c.id+'" style="border-color:#b65b5b;color:#ffb4aa">Löschen</button></td></tr>').join("")+
      '</tbody></table></div>';
    box.querySelectorAll("[data-open-case]").forEach(b=>b.onclick=()=>{const c=data.find(x=>x.id===b.dataset.openCase);activeConsultation=c;editingConsultationId=c.id;comparisonSnapshot=c.product_snapshot||[];comparisonIds=comparisonSnapshot.map(p=>String(p.id));mode="berater";selectedFamily=null;render();});
    box.querySelectorAll("[data-case-status]").forEach(el=>el.onchange=async()=>{const {error}=await window.supabaseClient.from("safe_consultations").update({status:el.value,updated_at:new Date().toISOString()}).eq("id",el.dataset.caseStatus);if(error)alert("Status konnte nicht gespeichert werden: "+error.message);});
    box.querySelectorAll("[data-delete-case]").forEach(b=>b.onclick=async()=>{
      const c=data.find(x=>x.id===b.dataset.deleteCase);
      if(!c||!confirm('Kundenberatung für "'+c.customer_name+'" wirklich endgültig löschen? Diese Aktion kann nicht rückgängig gemacht werden.'))return;
      b.disabled=true;
      const {error}=await window.supabaseClient.from("safe_consultations").delete().eq("id",c.id);
      if(error){alert("Beratung konnte nicht gelöscht werden: "+error.message);b.disabled=false;return;}
      bindCustomerCases();
    });
  }
  function fireLabel(p){const t=p.fire_protection_type||"unknown";if(t==="tested")return (p.fire_minutes||"Dauer offen")+" Minuten · "+(p.fire_standard||"Prüfnorm nicht angegeben");if(t==="none")return "Ohne Feuerschutz";if(t==="conditional")return "Bedingter Feuerschutz";return "Keine Angabe"}
  function compareRows(){return [["Kategorie",p=>p.category],["Artikelnummer",p=>p.article_number],["Einbruchschutz-Norm",p=>p.security_standard],["Sicherheitsklasse",p=>p.security_class],["Feuerschutz",fireLabel],["Versicherungswert privat",p=>p.insured_private!=null?euro(p.insured_private):null],["Versicherungswert gewerblich",p=>p.insured_commercial!=null?euro(p.insured_commercial):null],["Außenmaße (H × B × T)",p=>p.height_mm||p.width_mm||p.depth_mm?[p.height_mm||"–",p.width_mm||"–",p.depth_mm||"–"].join(" × ")+" mm":null],["Innenmaße (H × B × T)",p=>p.inner_height_mm||p.inner_width_mm||p.inner_depth_mm?[p.inner_height_mm||"–",p.inner_width_mm||"–",p.inner_depth_mm||"–"].join(" × ")+" mm":null],["Gewicht",p=>p.weight_kg!=null?p.weight_kg+" kg":null],["Innenvolumen",p=>p.volume_l!=null?p.volume_l+" l":null],["Schlossart",p=>p.lock_type],["Verfügbarkeit",p=>p.stock_status==="in_stock"?"Lagernd im Geschäft":"Muss bestellt werden"],["Verkaufspreis inkl. MwSt.",p=>p.sale_price_gross!=null?euro(p.sale_price_gross):"Preis auf Anfrage"]]}
  function createComparisonPdf(){const chosen=selectedComparisonProducts();if(chosen.length<2||chosen.length>3){alert("Bitte wähle zwei oder drei Tresore aus.");return}const win=window.open("","_blank");if(!win){alert("Der PDF-Druck wurde vom Browser blockiert. Bitte Pop-ups für diese App erlauben und erneut versuchen.");return}const rows=compareRows();const tableRows=rows.map(([label,get])=>'<tr><th>'+esc(label)+'</th>'+chosen.map(p=>'<td>'+esc(get(p)||"Keine Angabe")+'</td>').join("")+'</tr>').join("");const date=new Date().toLocaleDateString("de-DE");const html='<!doctype html><html lang="de"><head><meta charset="utf-8"><title>Tresorvergleich – Schlüsseldienst Höhne</title><style>@page{size:A4 landscape;margin:14mm}*{box-sizing:border-box}body{font-family:Arial,sans-serif;color:#17283b;margin:0;font-size:11px}.head{display:flex;justify-content:space-between;align-items:flex-end;border-bottom:3px solid #173e63;padding-bottom:12px;margin-bottom:18px}.brand{font-size:19px;font-weight:800;color:#173e63}.sub{color:#64748b;margin-top:4px}.date{color:#64748b}h1{font-size:22px;margin:0 0 5px;color:#173e63}.intro{margin:0 0 16px;color:#526477}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{padding:9px 10px;border:1px solid #d7e0e8;vertical-align:top;overflow-wrap:anywhere}thead th{background:#173e63;color:white;font-size:13px;text-align:left}tbody th{width:19%;background:#edf2f7;text-align:left;color:#263e56}tbody td{background:#fff}tbody tr:nth-child(even) td{background:#f8fafc}.price-row th,.price-row td{font-weight:800;font-size:15px}.price-row td{color:#0d6840;background:#eaf7ef!important}.foot{margin-top:16px;padding-top:9px;border-top:1px solid #d7e0e8;color:#64748b;font-size:9px;line-height:1.5}.actions{margin:18px 0}.actions button{background:#173e63;color:#fff;border:0;border-radius:6px;padding:10px 16px;font-weight:bold;cursor:pointer}@media print{.actions{display:none}body{-webkit-print-color-adjust:exact;print-color-adjust:exact}}</style></head><body><header class="head"><div><div class="brand">SCHLÜSSELDIENST HÖHNE</div><div class="sub">Tresorberatung · Produktvergleich</div></div><div class="date">Erstellt am '+date+'</div></header><h1>Ihre Tresor-Auswahl im Vergleich</h1><p class="intro">Die folgende Übersicht stellt die ausgewählten Modelle anhand der bei uns hinterlegten Produktdaten gegenüber.</p><table><thead><tr><th>Merkmal</th>'+chosen.map(p=>'<th>'+esc(p.model)+'</th>').join("")+'</tr></thead><tbody>'+tableRows+'</tbody></table><div class="foot">Hinweis: Versicherungswerte sind katalogabhängige Richtwerte und keine Versicherungszusage. Technische Angaben entsprechen dem bei der Beratung hinterlegten Datenstand. Preise verstehen sich inklusive gesetzlicher Umsatzsteuer. Verfügbarkeit vorbehaltlich zwischenzeitlichem Verkauf.</div><div class="actions"><button type="button" onclick="window.close()">← Zurück zur Tresorberatung</button> <button type="button" onclick="window.print()">PDF drucken / speichern</button></div><script>window.addEventListener("load",function(){setTimeout(function(){window.print()},350)})</script></body></html>';win.document.open();win.document.write(html);win.document.close()}
  async function printPriceTag(p){
    if(!p)return;
    let svg;
    try{
      const response=await fetch("/assets/Preisschild-A6.svg",{cache:"no-store"});
      if(!response.ok)throw new Error("SVG-Vorlage nicht gefunden");
      svg=await response.text();
    }catch(error){
      alert("Die originale A6-SVG-Vorlage fehlt noch unter assets/Preisschild-A6.svg. Bitte die Datei dort im Projekt ablegen.");
      return;
    }
    const xml=new DOMParser().parseFromString(svg,"image/svg+xml");
    if(xml.querySelector("parsererror")){alert("Die A6-SVG-Vorlage konnte nicht gelesen werden.");return}
    const texts=Array.from(xml.querySelectorAll("text"));
    const normalizeText=value=>String(value??"").trim().replace(/\\s+/g," ");
    const setText=(oldValue,newValue)=>{
      const node=texts.find(el=>normalizeText(el.textContent)===normalizeText(oldValue));
      if(node)node.textContent=String(newValue??"–");
      return node;
    };
    const fitText=(node,maxChars,baseSize,minSize)=>{
      if(!node)return;
      const ratio=Math.min(1,maxChars/Math.max(maxChars,String(node.textContent).length));
      node.style.fontSize=Math.max(minSize,baseSize*ratio)+"px";
    };
    const standard=[p.security_standard,p.security_class].filter(Boolean).join(" ")||"Keine Angabe";
    let fire="Keine Angabe";
    if(p.fire_protection_type==="none")fire="Ohne Feuerschutz";
    else if(p.fire_protection_type==="conditional")fire="Bedingter Feuerschutz";
    else if(p.fire_protection_type==="tested"){
      const mins=p.fire_minutes?String(p.fire_minutes)+" Minuten":null;
      const detail=String(p.fire_standard||"").match(/(?:LFS|DIS)\\s*\\d+\\s*P?/i)?.[0]||"";
      fire=[mins,detail].filter(Boolean).join(" ")||"Geprüfter Feuerschutz";
    }
    const weight=p.weight_kg!=null?String(p.weight_kg).replace(".",",")+" kg":"Keine Angabe";
    const dim=p.height_mm||p.width_mm||p.depth_mm
      ?[p.height_mm,p.width_mm,p.depth_mm].map(v=>v?String(Number(v)/10).replace(".",","):"–").join(" × ")+" in cm"
      :"Keine Angabe";
    const insuredValues=[p.insured_private?("privat bis "+euro(p.insured_private)):null,p.insured_commercial?("gewerblich bis "+euro(p.insured_commercial)):null].filter(Boolean);
    const insured=insuredValues.join(" · ")||"Keine Angabe";
    const price=p.sale_price_gross!=null?euro(p.sale_price_gross):"Preis auf Anfrage";
    const replacements=[
      ["Rottner Titan 30 Fire Blue",p.model||"Produkt"],
      ["Wertschutztresor mit Feuerschutz",p.description||p.category||"Tresor"],
      ["EN 14450 S2",standard],
      ["60 Minuten Papier",fire],
      ["41kg",weight],
      ["40 ×  35 ×  29 in cm",dim],
      ["S2 privat bis 20.000€",insured],
      ["807,00 €",price]
    ];
    const changed=replacements.map(([oldValue,newValue])=>setText(oldValue,newValue));
    fitText(changed[0],29,59.055,34);
    fitText(changed[1],40,33,21);
    // Technische Werte leicht vergrößern, Beschriftungen und Layout bleiben unverändert.
    fitText(changed[2],19,29.5,20);
    fitText(changed[3],19,29.5,20);
    fitText(changed[4],12,29.5,20);
    fitText(changed[5],24,29.5,18);
    // Versicherungswerte zweizeilig ausgeben, damit beide Angaben innerhalb des Datenkastens bleiben.
    const insuredNode=changed[6];
    if(insuredNode){
      insuredNode.textContent="";
      insuredNode.style.fontSize="22.5px";
      const privateLine=xml.createElementNS("http://www.w3.org/2000/svg","tspan");
      privateLine.setAttribute("x","34.016px");
      privateLine.setAttribute("dy","0");
      privateLine.textContent=insuredValues[0]||"Privat: Keine Angabe";
      const commercialLine=xml.createElementNS("http://www.w3.org/2000/svg","tspan");
      commercialLine.setAttribute("x","34.016px");
      commercialLine.setAttribute("dy","25px");
      commercialLine.textContent=insuredValues[1]||"Gewerblich: Keine Angabe";
      insuredNode.append(privateLine,commercialLine);
      fitText(privateLine,28,22.5,19);
      fitText(commercialLine,28,22.5,19);
    }
    const insuredHeading=texts.find(el=>normalizeText(el.textContent)==="Verischerbar");
    if(insuredHeading)insuredHeading.textContent="Versicherbar";
    // Datenkasten nach rechts und unten erweitern; der neue weiße Hintergrund deckt die alte Kontur ab.
    const dataGroup=xml.querySelector('g[transform="matrix(1,0,0,1,20.685046,523.746319)"]');
    if(dataGroup){
      const panel=xml.createElementNS("http://www.w3.org/2000/svg","rect");
      panel.setAttribute("x","17");
      panel.setAttribute("y","60");
      panel.setAttribute("width","335");
      panel.setAttribute("height","490");
      panel.setAttribute("fill","#ffffff");
      panel.setAttribute("stroke","#aeb9c5");
      panel.setAttribute("stroke-width","1.5");
      dataGroup.insertBefore(panel,dataGroup.firstChild);
      ["Gewicht","41kg","Maße"].forEach(label=>{
        const node=texts.find(el=>normalizeText(el.textContent)===label);
        if(node){
          const y=parseFloat(node.getAttribute("y"));
          node.setAttribute("y",(y+20)+"px");
        }
      });
      const dimensions=texts.find(el=>normalizeText(el.textContent).replace(/\s+/g," ")==="40 × 35 × 29 in cm");
      if(dimensions){
        const y=parseFloat(dimensions.getAttribute("y"));
        dimensions.setAttribute("y",(y+20)+"px");
      }
    }
    fitText(changed[7],12,100.394,58);
    const svgMarkup=new XMLSerializer().serializeToString(xml.documentElement);
    const familyImage=products.find(item=>familyKey(item)===familyKey(p)&&item.image_url)?.image_url||null;
    const imageUrl=p.image_url||familyImage;
    const productImage=imageUrl?'<img class="product-image" src="'+esc(imageUrl)+'" alt="'+esc(p.model||"Tresor")+'" onerror="this.style.display=\'none\'">':"";
    const win=window.open("","_blank");
    if(!win){alert("Bitte Pop-ups für diese App erlauben.");return}
    win.document.open();
    win.document.write('<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Preisschild – '+esc(p.model||"Produkt")+'</title><style>@page{size:106mm 148mm;margin:0}*{box-sizing:border-box}html,body{margin:0;padding:0;min-height:100%;font-family:Arial,sans-serif}body{background:#e8edf2;-webkit-print-color-adjust:exact;print-color-adjust:exact}.toolbar{position:sticky;top:0;z-index:2;background:#102b3f;color:#fff;padding:12px;display:flex;justify-content:center;gap:10px}.toolbar button{border:0;border-radius:8px;background:#fff;color:#102b3f;font-size:16px;font-weight:700;padding:12px 18px;cursor:pointer}.hint{text-align:center;color:#334155;font-size:13px;padding:8px}.sheet{position:relative;width:106mm;height:148mm;margin:12px auto;overflow:hidden;background:#fff;box-shadow:0 2px 14px #0003}.sheet svg{display:block;width:106mm;height:148mm}.product-image{position:absolute;right:3.5%;top:23%;width:45%;height:47%;object-fit:contain;object-position:center;z-index:1;pointer-events:none}@media print{html,body{width:106mm;height:148mm;background:#fff}.toolbar,.hint{display:none!important}.sheet{margin:0;box-shadow:none}}</style></head><body><div class="toolbar"><button type="button" onclick="window.print()">Drucken / als PDF sichern</button></div><div class="hint">Tippe auf „Drucken / als PDF sichern“, um den Druckdialog zu öffnen. Auf dem iPhone kannst du dort über „Teilen“ auch als PDF sichern.</div><main class="sheet">'+svgMarkup+productImage+'</main></body></html>');
    win.document.close();
  }
  function productCard(p){const marked=comparisonIds.includes(String(p.id));return '<article class="tresor-card"><span class="tresor-tag">'+esc(p.category||"Wertschutzschrank")+'</span><span class="tresor-tag">'+(p.stock_status==="in_stock"?"Lagernd im Geschäft":"Muss bestellt werden")+'</span><h3>'+esc(p.model)+'</h3><div class="tresor-muted">Art.-Nr. '+esc(p.article_number||"–")+'</div><p>'+esc(p.security_standard||"Keine Angabe")+' · Klasse '+esc(p.security_class||"–")+'</p><p>Feuerschutz: '+(p.fire_protection_type==="conditional"?"Bedingt feuerbeständig":p.fire_protection_type==="tested"?(esc(p.fire_minutes||"Dauer offen")+" Min. · "+esc(p.fire_standard||"Prüfnorm offen")):p.fire_protection_type==="none"?"Ohne Feuerschutz":p.fire_protection_type==="unknown"?"Keine Angabe":(p.fire_minutes?esc(p.fire_minutes)+" Min. · "+esc(p.fire_standard||"Norm nicht hinterlegt"):"Keine Angabe"))+'</p><p>Versicherbar privat: '+(p.insured_private?euro(p.insured_private):"Keine Angabe")+'<br>gewerblich: '+(p.insured_commercial?euro(p.insured_commercial):"Keine Angabe")+'</p><p class="tresor-muted">Außenmaße: '+esc(p.height_mm||"–")+' × '+esc(p.width_mm||"–")+' × '+esc(p.depth_mm||"–")+' mm · '+esc(p.weight_kg||"–")+' kg</p><p class="tresor-muted">Innenmaße: '+esc(p.inner_height_mm||"–")+' × '+esc(p.inner_width_mm||"–")+' × '+esc(p.inner_depth_mm||"–")+' mm · Volumen: '+esc(p.volume_l||"–")+' l · Schloss: '+esc(p.lock_type||"–")+'</p><div class="price">'+(p.sale_price_gross!=null?euro(p.sale_price_gross):"Preis auf Anfrage")+'</div><div class="tresor-muted">Eigener Verkaufspreis inkl. MwSt.</div><button type="button" class="tresor-mark-btn '+(marked?"selected":"")+'" data-mark-compare="'+esc(p.id)+'">'+(marked?"✓ Für Vergleich ausgewählt":"＋ Für Vergleich merken")+'</button><button type="button" class="btnS" data-price-tag="'+esc(p.id)+'">Preisschild drucken</button></article>'}
  // Gruppiert Varianten automatisch über die Serienbezeichnung. Explizite family_name-Angaben haben Vorrang.
  function familyKey(p){
    if(p.family_name&&p.family_name.trim())return p.family_name.trim();
    const model=String(p.model||"").trim();
    // Entfernt nur typische Varianten-Endungen wie "30", "40 EL", "1 EL".
    return model.replace(/\s+\d+(?:\s+IT)?(?:\s*EL)?$/i,"").trim()||model;
  }
  function showResults(){const fireChoice=advisorFilters.fire,standard=advisorFilters.standard,cls=advisorFilters.cls,insured=Number(advisorFilters.insured||0),use=advisorFilters.use,price=Number(advisorFilters.price||0),group=advisorFilters.group;const list=products.filter(p=>{const type=p.fire_protection_type||((p.fire_minutes&&p.fire_standard)?"tested":"unknown");const fireMatch=!fireChoice||(fireChoice.startsWith("tested:")?type==="tested"&&Number(p.fire_minutes)===Number(fireChoice.split(":")[1]):type===fireChoice);const groupMatch=!group||String(p.category||"").toLocaleLowerCase("de")===group.toLocaleLowerCase("de");return p.active!==false&&groupMatch&&fireMatch&&(!standard||p.security_standard===standard)&&(!cls||p.security_class===cls)&&(!insured||Number(use==="private"?p.insured_private:p.insured_commercial)>=insured)&&(!price||(p.sale_price_gross!=null&&Number(p.sale_price_gross)<=price))});const out=document.getElementById("tresorResults");const groups=new Map();list.forEach(p=>{const key=familyKey(p);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(p)});if(selectedFamily){const variants=groups.get(selectedFamily)||[];out.innerHTML='<div class="tresor-series-back"><button class="btnS" id="backToSeries">← Alle Tresorserien</button><h3>'+esc(selectedFamily)+'</h3><p class="tresor-muted">'+variants.length+' Varianten erhältlich</p></div>'+variants.map(productCard).join("");document.getElementById("backToSeries").onclick=()=>{selectedFamily=null;showResults()};out.querySelectorAll("[data-mark-compare]").forEach(b=>b.onclick=()=>toggleComparison(b.dataset.markCompare));out.querySelectorAll("[data-price-tag]").forEach(b=>b.onclick=()=>printPriceTag(products.find(p=>String(p.id)===String(b.dataset.priceTag))));renderCompareBar();return}const cards=[];for(const [key,items] of groups){const priced=items.map(p=>Number(p.sale_price_gross)).filter(n=>Number.isFinite(n)&&n>0);const lowest=priced.length?Math.min(...priced):null;cards.push('<button class="tresor-series-card" type="button" data-family="'+esc(key)+'"><span class="tresor-series-name">'+esc(key)+'</span><span class="tresor-series-count">'+items.length+(items.length===1?" Variante erhältlich":" Varianten erhältlich")+(lowest!==null?'<br><strong class="tresor-series-price">ab '+euro(lowest)+' brutto</strong>':'<br><span class="tresor-muted">Preis auf Anfrage</span>')+'</span><span class="tresor-series-arrow">›</span></button>')}out.innerHTML=cards.length?cards.join(""):'<div class="tresor-empty">Keine passenden Tresore gefunden. Passe die Anforderungen an oder ergänze weitere Modelle in der Produktverwaltung.</div>';out.querySelectorAll("[data-family]").forEach(b=>b.onclick=()=>{selectedFamily=b.dataset.family;showResults()});renderCompareBar()}
  function productsView(){return '<div class="tresor-panel"><div class="sec">ALLE TRESORPRODUKTE ('+products.length+')</div><p class="tresor-muted">Übersicht aller in der Datenbank hinterlegten Produkte. Änderungen nimmst du in der Produktverwaltung vor.</p><div class="tresor-field" style="max-width:420px;margin-bottom:14px"><label>Produkte durchsuchen</label><input id="productListSearch" type="search" placeholder="Modell, Artikelnummer oder Kategorie"></div><div id="allProductsList"></div></div>'}
  function bindProductsView(){const search=document.getElementById("productListSearch");const draw=()=>{const q=(search.value||"").toLocaleLowerCase("de");const rows=products.filter(p=>[p.model,p.article_number,p.category,p.family_name].some(v=>String(v||"").toLocaleLowerCase("de").includes(q)));document.getElementById("allProductsList").innerHTML='<div class="tresor-table-wrap"><table class="tresor-table"><thead><tr><th>Modell</th><th>Artikelnummer</th><th>Kategorie</th><th>Sicherheitsklasse</th><th>Preis brutto</th><th>Verfügbarkeit</th><th>Status</th><th>Aktion</th></tr></thead><tbody>'+rows.map(p=>'<tr><td><strong>'+esc(p.model)+'</strong><br><small>'+esc(p.family_name||"")+'</small></td><td>'+esc(p.article_number||"–")+'</td><td>'+esc(p.category||"–")+'</td><td>'+esc([p.security_standard,p.security_class].filter(Boolean).join(" ")||"–")+'</td><td>'+(p.sale_price_gross!=null?euro(p.sale_price_gross):"Preis auf Anfrage")+'</td><td>'+(p.stock_status==="in_stock"?"Lagernd":"Bestellware")+'</td><td>'+(p.active===false?"Deaktiviert":"Aktiv")+'</td><td><button class="btnS" type="button" data-product-edit="'+esc(p.id)+'">Bearbeiten</button> <button class="btnS" type="button" data-price-tag="'+esc(p.id)+'">Preisschild</button></td></tr>').join("")+'</tbody></table></div>'+(rows.length?"":'<div class="tresor-empty">Keine passenden Produkte gefunden.</div>')};search.oninput=draw;draw();document.getElementById("allProductsList").addEventListener("click",e=>{const tag=e.target.closest("[data-price-tag]");if(tag){printPriceTag(products.find(p=>String(p.id)===String(tag.dataset.priceTag)));return}const b=e.target.closest("[data-product-edit]");if(!b)return;editingId=b.dataset.productEdit;adminStage="form";mode="verwaltung";render()})}
  function admin(){
    if(adminStage==="menu")return '<div class="tresor-home-grid"><button type="button" class="tresor-home-card" id="startNewProduct"><span class="tresor-home-icon">＋</span><strong>Neues Produkt anlegen</strong><small>Leere Eingabemaske öffnen</small><b>›</b></button><button type="button" class="tresor-home-card" id="startEditProduct"><span class="tresor-home-icon">⌕</span><strong>Produkt bearbeiten / löschen</strong><small>Nach Modellname oder Artikelnummer suchen</small><b>›</b></button></div>';
    if(adminStage==="search")return '<div class="tresor-panel"><div class="sec">PRODUKT SUCHEN</div><p class="tresor-muted">Wähle die gewünschte Suchart. Anschließend kannst du das passende Modell auswählen.</p><div class="tresor-actions"><button type="button" class="btnP" id="searchByModel">Nach Modellname suchen</button><button type="button" class="btnP" id="searchByArticle">Nach Artikelnummer suchen</button></div><div id="productSearchModal" class="tresor-filter-modal"><div class="tresor-filter-dialog"><div class="tresor-filter-dialog-head"><strong id="productSearchTitle"></strong><button type="button" class="btnS" id="closeProductSearch">Schließen ✕</button></div><div class="tresor-field"><label id="productSearchLabel"></label><input id="productSearchInput" type="search" autocomplete="off"></div><div id="productSearchResults" class="tresor-product-search-results"></div></div></div><div class="tresor-actions"><button type="button" class="btnS" id="backToProductMenu">← Zurück</button></div></div>';
    return '<div class="tresor-panel"><div class="sec">'+(editingId?'PRODUKT BEARBEITEN':'NEUES PRODUKT ANLEGEN')+'</div><div class="tresor-actions"><button class="btnS" id="backToProductMenu">← Zurück zur Produktverwaltung</button></div><div class="tresor-panel"><div class="sec">TRESOR ANLEGEN / BEARBEITEN</div><form id="safeForm"><div class="tresor-grid"><div class="tresor-field"><label>Hersteller</label><input id="pManufacturer" value="Rottner" required></div><div class="tresor-field"><label>Modellname *</label><input id="pModel" required></div><div class="tresor-field"><label>Tresorserie (für Kundenübersicht)</label><input id="pFamily" placeholder="z. B. Praktik oder Exclusive Blue EL"></div><div class="tresor-field"><label>Artikelnummer</label><input id="pArticle"></div><div class="tresor-field"><label>Kategorie</label><select id="pCategory"><option value="">Bitte auswählen</option><option>Wertschutzschrank</option><option>Feuerschutztresor</option><option>Möbeltresor</option><option>Waffenschrank</option><option>Schlüsseltresor</option><option>Einwurftresor</option><option>Wandtresor</option><option>Datentresor</option><option>Hotelzimmertresor</option><option>Sonstiges</option></select></div><div class="tresor-field"><label>Einbruchschutz-Norm</label><select id="pStandard"><option value="">Keine Angabe</option><option>EN 1143-1</option><option>EN 14450</option></select></div><div class="tresor-field"><label>Sicherheitsklasse</label><input id="pClass" placeholder="z. B. I, II, S1"></div><div class="tresor-field"><label>Feuerschutz</label><select id="pFireProtection"><option value="unknown">Keine Angabe</option><option value="none">Ohne Feuerschutz</option><option value="conditional">Bedingter Feuerschutz</option><option value="tested:30">30 Minuten</option><option value="tested:60">60 Minuten</option><option value="tested:120">120 Minuten</option></select></div><div class="tresor-field"><label>Feuerschutz-Prüfnorm</label><input id="pFireStandard" placeholder="z. B. EN 15659 / LFS 30P"></div><div class="tresor-field"><label>Versicherungswert privat (€)</label><input id="pPrivate" type="number" min="0" step="1"></div><div class="tresor-field"><label>Versicherungswert gewerblich (€)</label><input id="pCommercial" type="number" min="0" step="1"></div><div class="tresor-field"><label>Höhe außen (mm)</label><input id="pHeight" type="number" min="0"></div><div class="tresor-field"><label>Breite außen (mm)</label><input id="pWidth" type="number" min="0"></div><div class="tresor-field"><label>Tiefe außen (mm)</label><input id="pDepth" type="number" min="0"></div><div class="tresor-field"><label>Gewicht (kg)</label><input id="pWeight" type="number" min="0" step="0.1"></div><div class="tresor-field"><label>Volumen innen (Liter)</label><input id="pVolume" type="number" min="0" step="0.1"></div><div class="tresor-field"><label>Innenhöhe (mm)</label><input id="pInnerHeight" type="number" min="0"></div><div class="tresor-field"><label>Innenbreite (mm)</label><input id="pInnerWidth" type="number" min="0"></div><div class="tresor-field"><label>Innentiefe (mm)</label><input id="pInnerDepth" type="number" min="0"></div><div class="tresor-field"><label>Schlossart</label><input id="pLockType" placeholder="z. B. Doppelbart / Elektronik"></div><div class="tresor-field"><label>Verfügbarkeit im Geschäft</label><select id="pStockStatus"><option value="to_order">Muss bestellt werden</option><option value="in_stock">Lagernd im Geschäft</option></select></div><div class="tresor-field"><label>Einkaufspreis (€)</label><input id="pPurchasePrice" type="number" min="0" step="0.01" placeholder="Netto-EK oder Brutto-EK"></div><div class="tresor-field"><label>Einkaufspreis eingegeben als</label><select id="pPurchasePriceType"><option value="net">Netto (empfohlen)</option><option value="gross">Brutto inkl. 19 % MwSt. (Vorsteuerabzug)</option></select></div><div class="tresor-field"><label>Gewünschte Handelsspanne (%)</label><input id="pMargin" type="number" min="0" max="90" step="0.5" value="30"></div><div class="tresor-field"><label>Manueller Verkaufspreis brutto (€)</label><input id="pPrice" type="number" min="0" step="0.01" placeholder="Wird bei EK-Kalkulation automatisch gesetzt"></div><div class="tresor-field" style="grid-column:1/-1"><div id="priceCalcPreview" class="tresor-calc-preview">Einkaufspreis eingeben – die Kalkulation wird hier live angezeigt.</div><small class="tresor-muted">Bei Brutto-EK wird die enthaltene Vorsteuer von 19 % herausgerechnet. Das setzt voraus, dass du zum Vorsteuerabzug berechtigt bist.</small></div><div class="tresor-field"><label>Produktbild-URL</label><input id="pImage" type="url" placeholder="https://…"></div><div class="tresor-field"><label>Aktiv</label><select id="pActive"><option value="true">Ja</option><option value="false">Nein / deaktiviert</option></select></div><div class="tresor-field"><label>Datenquelle / Katalogseite</label><input id="pSource" placeholder="z. B. Praktik-Flyer, Seite 2"></div><div class="tresor-field"><label>Quellenstand</label><input id="pSourceDate" placeholder="z. B. 2026 / 01-2026"></div><div class="tresor-field"><label>Interne Notizen</label><input id="pNotes"></div></div><div class="tresor-actions"><button class="btnP" type="submit">Tresor speichern</button><button class="btnS" type="button" id="clearSafeForm">Eingabe leeren</button></div><div id="safeFormMsg" class="tresor-status"></div></form></div><div class="tresor-actions">'+(editingId?'<button class="btnS" type="button" id="printCurrentProduct">Preisschild drucken</button> <button class="btnS" id="deleteCurrentProduct" style="border-color:#b65b5b;color:#ffb4aa">Produkt löschen</button>':'')+'</div></div>';
  }
  function bindAdmin(){
    if(adminStage==="menu"){document.getElementById("startNewProduct").addEventListener("click",()=>{editingId=null;adminStage="form";render()});document.getElementById("startEditProduct").addEventListener("click",()=>{editingId=null;adminStage="search";render()});return}
    if(adminStage==="search"){document.getElementById("backToProductMenu").addEventListener("click",()=>{adminStage="menu";render()});document.getElementById("searchByModel").addEventListener("click",()=>openProductSearch("model"));document.getElementById("searchByArticle").addEventListener("click",()=>openProductSearch("article_number"));document.getElementById("closeProductSearch").addEventListener("click",closeProductSearch);document.getElementById("productSearchModal").onclick=e=>{if(e.target.id==="productSearchModal")closeProductSearch()};return}
    document.getElementById("safeForm").onsubmit=saveProduct;document.getElementById("clearSafeForm").onclick=clearForm;document.getElementById("backToProductMenu").addEventListener("click",()=>{editingId=null;adminStage="menu";render()});["pPurchasePrice","pPurchasePriceType","pMargin"].forEach(id=>document.getElementById(id).addEventListener("input",updatePricePreview));document.getElementById("pPurchasePriceType").addEventListener("change",updatePricePreview);document.getElementById("deleteCurrentProduct")?.addEventListener("click",()=>deleteProduct(editingId));document.getElementById("printCurrentProduct")?.addEventListener("click",()=>printPriceTag(products.find(p=>String(p.id)===String(editingId))));if(editingId)editProduct(editingId);else clearForm();updatePricePreview();
  }
  function openProductSearch(field){adminSearchField=field;const modal=document.getElementById("productSearchModal"),input=document.getElementById("productSearchInput");document.getElementById("productSearchTitle").textContent=field==="model"?"Nach Modellname suchen":"Nach Artikelnummer suchen";document.getElementById("productSearchLabel").textContent=field==="model"?"Modellname eingeben":"Artikelnummer eingeben";input.placeholder=field==="model"?"z. B. Dakota oder Fire Hero":"z. B. T06534";input.value="";document.getElementById("productSearchResults").innerHTML='<div class="tresor-empty">Gib einen Suchbegriff ein.</div>';modal.classList.add("open");input.oninput=drawProductSearchResults;input.focus()}
  function closeProductSearch(){document.getElementById("productSearchModal")?.classList.remove("open")}
  function drawProductSearchResults(){const q=val("productSearchInput").trim().toLocaleLowerCase("de"),box=document.getElementById("productSearchResults");if(!q){box.innerHTML='<div class="tresor-empty">Gib einen Suchbegriff ein.</div>';return}const matches=products.filter(p=>String(p[adminSearchField]||"").toLocaleLowerCase("de").includes(q)).slice(0,50);box.innerHTML=matches.length?matches.map(p=>'<button type="button" class="tresor-product-search-result" data-select-product="'+esc(p.id)+'"><span><strong>'+esc(p.model)+'</strong><small>Artikel-Nr. '+esc(p.article_number||"–")+' · '+esc(p.category||"–")+'</small></span><b>Auswählen ›</b></button>').join(""):'<div class="tresor-empty">Keine passenden Produkte gefunden.</div>';box.querySelectorAll("[data-select-product]").forEach(b=>b.onclick=()=>{editingId=b.dataset.selectProduct;adminStage="form";closeProductSearch();render()})}
  async function deleteProduct(id){const p=products.find(x=>String(x.id)===String(id));if(!p||!confirm('Produkt "'+p.model+'" ('+(p.article_number||"ohne Artikelnummer")+') wirklich endgültig löschen?'))return;const {error}=await window.supabaseClient.from("safe_products").delete().eq("id",id);if(error){alert("Produkt konnte nicht gelöscht werden: "+error.message);return;}if(String(editingId)===String(id)){editingId=null;adminStage="menu"}await loadProducts()}
  function clearForm(){editingId=null;document.getElementById("safeForm").reset();document.getElementById("pManufacturer").value="";document.getElementById("pMargin").value="";document.getElementById("safeFormMsg").textContent="";updatePricePreview()}
  function priceCalculation(){const entered=Number(val("pPurchasePrice")),type=val("pPurchasePriceType")||"net",margin=Number(val("pMargin"));if(!(entered>0)||!Number.isFinite(margin)||margin<0||margin>=100)return null;const purchaseNet=type==="gross"?entered/1.19:entered;const saleNet=purchaseNet/(1-margin/100);const vat=saleNet*.19;return {purchaseInput:entered,purchaseNet,margin,saleNet,vat,saleGross:saleNet+vat,profit:saleNet-purchaseNet}}
  function updatePricePreview(){const box=document.getElementById("priceCalcPreview");if(!box)return;const c=priceCalculation();if(!c){box.innerHTML="Einkaufspreis eingeben und eine Handelsspanne zwischen 0 und 99,5 % wählen.";return}box.innerHTML='<div class="tresor-calc-title">Kalkulierter Verkaufspreis brutto</div><div class="tresor-calc-price">'+euro(c.saleGross)+'</div><div class="tresor-calc-details"><span class="tresor-calc-ek">EK netto: '+euro(c.purchaseNet)+'</span><span>Nettoverkauf: '+euro(c.saleNet)+'</span><span>19 % MwSt.: '+euro(c.vat)+'</span><span class="tresor-calc-profit">Rohertrag: '+euro(c.profit)+'</span></div>';const pPrice=document.getElementById("pPrice");if(pPrice)pPrice.value=c.saleGross.toFixed(2)}
  function editProduct(id){const p=products.find(x=>String(x.id)===String(id));if(!p)return;editingId=p.id;const category=document.getElementById("pCategory");if(p.category&&!Array.from(category.options).some(o=>o.value===p.category)){const option=document.createElement("option");option.value=p.category;option.textContent=p.category;category.appendChild(option)}const map={pManufacturer:"manufacturer",pModel:"model",pFamily:"family_name",pArticle:"article_number",pCategory:"category",pStandard:"security_standard",pClass:"security_class",pFireProtection:"fire_protection_type",pFireStandard:"fire_standard",pVolume:"volume_l",pInnerHeight:"inner_height_mm",pInnerWidth:"inner_width_mm",pInnerDepth:"inner_depth_mm",pLockType:"lock_type",pPrivate:"insured_private",pCommercial:"insured_commercial",pHeight:"height_mm",pWidth:"width_mm",pDepth:"depth_mm",pWeight:"weight_kg",pPrice:"sale_price_gross",pPurchasePrice:"purchase_price_input",pPurchasePriceType:"purchase_price_type",pMargin:"margin_percent",pStockStatus:"stock_status",pImage:"image_url",pActive:"active",pSource:"source_reference",pSourceDate:"source_date",pNotes:"notes"};Object.entries(map).forEach(([id,k])=>{const el=document.getElementById(id);if(el)el.value=p[k]??""});document.getElementById("pFireProtection").value=p.fire_protection_type==="tested"&&[30,60,120].includes(Number(p.fire_minutes))?"tested:"+p.fire_minutes:(p.fire_protection_type||"unknown");window.scrollTo({top:0,behavior:"smooth"})}
  async function saveProduct(e){e.preventDefault();const msg=document.getElementById("safeFormMsg");const n=id=>val(id)===""?null:Number(val(id));const calc=priceCalculation();const p={manufacturer:val("pManufacturer").trim()||"Rottner",model:val("pModel").trim(),family_name:val("pFamily").trim()||null,article_number:val("pArticle").trim()||null,category:val("pCategory"),security_standard:val("pStandard")||null,security_class:val("pClass").trim()||null,fire_minutes:val("pFireProtection").startsWith("tested:")?Number(val("pFireProtection").split(":")[1]):null,fire_protection_type:val("pFireProtection").startsWith("tested:")?"tested":(val("pFireProtection")||"unknown"),fire_standard:val("pFireProtection").startsWith("tested:")?(val("pFireStandard").trim()||null):null,volume_l:n("pVolume"),inner_height_mm:n("pInnerHeight"),inner_width_mm:n("pInnerWidth"),inner_depth_mm:n("pInnerDepth"),lock_type:val("pLockType").trim()||null,insured_private:n("pPrivate"),insured_commercial:n("pCommercial"),height_mm:n("pHeight"),width_mm:n("pWidth"),depth_mm:n("pDepth"),weight_kg:n("pWeight"),sale_price_gross:calc?Number(calc.saleGross.toFixed(2)):n("pPrice"),purchase_price_input:n("pPurchasePrice"),purchase_price_type:val("pPurchasePriceType")||"net",margin_percent:val("pMargin")===""?30:Number(val("pMargin")),stock_status:val("pStockStatus")||"to_order",image_url:val("pImage").trim()||null,active:val("pActive")==="true",source_reference:val("pSource").trim()||null,source_date:val("pSourceDate").trim()||null,notes:val("pNotes").trim()||null};let q=window.supabaseClient.from("safe_products");const result=editingId?await q.update(p).eq("id",editingId).select():await q.insert(p).select();if(result.error){msg.textContent="Speichern fehlgeschlagen: "+result.error.message;msg.classList.add("error");return}msg.textContent="Tresor wurde gespeichert.";msg.classList.remove("error");editingId=null;adminStage="menu";await loadProducts()}
  async function loadProducts(){const {data,error}=await window.supabaseClient.from("safe_products").select("*").order("model");if(error){if(error.code==="42P01"||error.message?.includes("safe_products")){root().innerHTML='<div class="tresor-wrap"><div class="tresor-panel"><h2>Datenbank noch nicht eingerichtet</h2><p class="tresor-muted">Bitte zuerst die SQL-Datei <strong>supabase/tresorberater.sql</strong> im Supabase SQL Editor ausführen. Danach die Seite neu laden.</p></div></div>';return}loginView("Produktdaten konnten nicht geladen werden: "+error.message);return}products=data||[];render()}
  async function init(){if(!window.supabaseClient){loginView("Supabase ist noch nicht verbunden. Bitte App neu laden.");return}const {data}=await window.supabaseClient.auth.getSession();session=data.session;if(!session){loginView();return}await loadProducts()}
  window.initTresorBerater=()=>{if(!initialized){initialized=true;shell()}init().catch(e=>loginView("Fehler: "+e.message))};
})();